package br.com.onda;
import android.app.*;import android.content.*;import android.graphics.*;import android.net.Uri;import android.os.*;import android.speech.RecognizerIntent;import android.view.*;import android.widget.*;import org.junit.*;import static org.junit.Assert.*;import static androidx.test.platform.app.InstrumentationRegistry.getInstrumentation;import java.io.*;import java.lang.reflect.*;import java.nio.file.Files;import java.util.*;import java.util.concurrent.atomic.AtomicReference;import org.json.JSONObject;
public class ImageMessagesTest {
 private final Instrumentation ins=getInstrumentation();private final Context c=ins.getTargetContext();private ImageSearchActivity screen;private final List<File> fixtures=new ArrayList<>();private final List<Instrumentation.ActivityMonitor> monitors=new ArrayList<>();
 private interface Check{boolean ready()throws Exception;}
 private void waitFor(Check check)throws Exception{for(int i=0;i<300;i++){boolean[] ready={false};ins.runOnMainSync(()->{try{ready[0]=check.ready();}catch(Exception e){throw new RuntimeException(e);}});if(ready[0])return;Thread.sleep(50);}fail("Image scenario timed out");}
 private Object field(String name)throws Exception{Field f=ImageSearchActivity.class.getDeclaredField(name);f.setAccessible(true);return f.get(screen);}
 private View find(View root,String label){if(label.contentEquals(root.getContentDescription()==null?"":root.getContentDescription()))return root;if(root instanceof ViewGroup)for(int i=0;i<((ViewGroup)root).getChildCount();i++){View v=find(((ViewGroup)root).getChildAt(i),label);if(v!=null)return v;}return null;}
 private View find(String label){return find(screen.findViewById(android.R.id.content),label);}
 private AtomicReference<Intent> chooser(){AtomicReference<Intent> captured=new AtomicReference<>();Instrumentation.ActivityMonitor monitor=new Instrumentation.ActivityMonitor(){@Override public Instrumentation.ActivityResult onStartActivity(Intent intent){if(Intent.ACTION_CHOOSER.equals(intent.getAction())){captured.set(intent);return new Instrumentation.ActivityResult(Activity.RESULT_CANCELED,null);}return null;}};ins.addMonitor(monitor);monitors.add(monitor);return captured;}
 private Intent send(AtomicReference<Intent> captured)throws Exception{waitFor(()->captured.get()!=null);Intent send=captured.get().getParcelableExtra(Intent.EXTRA_INTENT);assertEquals(Intent.ACTION_SEND,send.getAction());assertTrue((send.getFlags()&Intent.FLAG_GRANT_READ_URI_PERMISSION)!=0);assertEquals(0,send.getFlags()&Intent.FLAG_GRANT_WRITE_URI_PERMISSION);Uri uri=send.getParcelableExtra(Intent.EXTRA_STREAM);assertNotNull(uri);assertEquals("content",uri.getScheme());assertEquals(c.getPackageName()+".share",uri.getAuthority());assertEquals(uri,send.getClipData().getItemAt(0).getUri());assertNull(send.getPackage());return send;}
 private byte[] bytes(Intent send)throws Exception{Uri uri=send.getParcelableExtra(Intent.EXTRA_STREAM);try(InputStream in=c.getContentResolver().openInputStream(uri);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return out.toByteArray();}}
 private void report(String name,JSONObject report)throws Exception{try(OutputStream out=new FileOutputStream(new File(c.getFilesDir(),name+".json"))){out.write(report.toString(2).getBytes("UTF-8"));}}
 @Before public void open(){screen=(ImageSearchActivity)ins.startActivitySync(new Intent(c,ImageSearchActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));ins.waitForIdleSync();}
 @After public void close(){for(Instrumentation.ActivityMonitor m:monitors)ins.removeMonitor(m);if(screen!=null){ins.runOnMainSync(screen::finish);ins.waitForIdleSync();}for(File f:fixtures)f.delete();}
 @Test public void voiceFindsGoodNightAndSharesEditedPngWithoutInternet()throws Exception{AtomicReference<Intent> recognized=new AtomicReference<>();Instrumentation.ActivityMonitor voice=new Instrumentation.ActivityMonitor(){@Override public Instrumentation.ActivityResult onStartActivity(Intent intent){if(RecognizerIntent.ACTION_RECOGNIZE_SPEECH.equals(intent.getAction())){recognized.set(intent);return new Instrumentation.ActivityResult(Activity.RESULT_CANCELED,null);}return null;}};ins.addMonitor(voice);monitors.add(voice);ins.runOnMainSync(()->find("Buscar imagens por voz").performClick());waitFor(()->recognized.get()!=null);assertEquals("pt-BR",recognized.get().getStringExtra(RecognizerIntent.EXTRA_LANGUAGE));Intent result=new Intent().putStringArrayListExtra(RecognizerIntent.EXTRA_RESULTS,new ArrayList<>(Arrays.asList("procure imagens de boa noite")));ins.runOnMainSync(()->screen.onActivityResult(VoiceSearch.REQUEST,Activity.RESULT_OK,result));waitFor(()->find("Personalizar mensagem Boa noite")!=null);AtomicReference<Intent> captured=chooser();ins.runOnMainSync(()->find("Personalizar mensagem Boa noite").performClick());waitFor(()->field("cardDialog")!=null&&((AlertDialog)field("cardDialog")).isShowing());ins.runOnMainSync(()->{try{((EditText)field("messageInput")).setText("Boa noite, família! Que o descanso traga paz e um lindo amanhã.");((Spinner)field("styles")).setSelection(3);Method update=ImageSearchActivity.class.getDeclaredMethod("preview");update.setAccessible(true);update.invoke(screen);}catch(Exception e){throw new RuntimeException(e);}});waitFor(()->((EditText)field("messageInput")).getLineCount()>1);ins.waitForIdleSync();Thread.sleep(200);Bitmap picture=ins.getUiAutomation().takeScreenshot();if(picture!=null)try(OutputStream out=new FileOutputStream(new File(c.getFilesDir(),"image-message-preview.png"))){picture.compress(Bitmap.CompressFormat.PNG,100,out);picture.recycle();}ins.runOnMainSync(()->{try{((AlertDialog)field("cardDialog")).getButton(AlertDialog.BUTTON_POSITIVE).performClick();}catch(Exception e){throw new RuntimeException(e);}});Intent send=send(captured);assertEquals("image/png",send.getType());byte[] png=bytes(send);Bitmap decoded=BitmapFactory.decodeByteArray(png,0,png.length);assertNotNull(decoded);assertEquals(1080,decoded.getWidth());assertEquals(1350,decoded.getHeight());assertTrue(png.length>20000);decoded.recycle();report("image-message-tests",new JSONObject().put("voiceIntentPortuguese",true).put("voiceResultFiltersGoodNight",true).put("editableMessageAndBackground",true).put("realPng1080x1350",true).put("nativeChooserReadOnlyGrant",true).put("noNetworkNeeded",true));}
 @Test public void onlinePhotoSharesActualImageWithCreditsAndPreservesCache()throws Exception{ImageCatalog.Photo photo=new ImageCatalog.Photo("Fixture.png","https://upload.wikimedia.org/wikipedia/commons/native-onda-fixture.png","https://commons.wikimedia.org/wiki/File:Fixture.png","Autor de teste","CC0","image/jpeg");File file=ImageNetwork.cached(c,photo.thumb);fixtures.add(file);Bitmap tiny=Bitmap.createBitmap(24,24,Bitmap.Config.ARGB_8888);tiny.eraseColor(Color.CYAN);try(OutputStream out=new FileOutputStream(file)){tiny.compress(Bitmap.CompressFormat.PNG,100,out);}tiny.recycle();byte[] original=Files.readAllBytes(file.toPath());AtomicReference<Intent> captured=chooser();ins.runOnMainSync(()->{find("Fotos da internet").performClick();try{((List<ImageCatalog.Photo>)field("photos")).add(photo);Method refresh=ImageSearchActivity.class.getDeclaredMethod("refreshRows");refresh.setAccessible(true);refresh.invoke(screen);}catch(Exception e){throw new RuntimeException(e);}});waitFor(()->find("Ver imagem Fixture.png")!=null);ins.runOnMainSync(()->find("Ver imagem Fixture.png").performClick());waitFor(()->field("photoDialog")!=null&&((AlertDialog)field("photoDialog")).isShowing());ins.runOnMainSync(()->{try{((AlertDialog)field("photoDialog")).getButton(AlertDialog.BUTTON_POSITIVE).performClick();}catch(Exception e){throw new RuntimeException(e);}});Intent send=send(captured);assertEquals("image/png",send.getType());assertArrayEquals(original,bytes(send));assertArrayEquals(original,Files.readAllBytes(file.toPath()));assertTrue(send.getStringExtra(Intent.EXTRA_TEXT).contains("CC0"));assertTrue(send.getStringExtra(Intent.EXTRA_TEXT).contains(photo.page));report("image-photo-tests",new JSONObject().put("sharesActualPhotoBytes",true).put("mimeCheckedFromImage",true).put("sourceAuthorLicenseIncluded",true).put("cachedSourcePreserved",true));}
}
